import {useState} from 'react';
type Value=number|string|boolean;
type Input={key:string;label:string;value:Value;default:Value;type:string};
type FailSafe={timeframe_minutes:number;consecutive_candles:number;loss_pct:number};
type Profit={partial_sell_pct?:number;gain_pct:number;giveback_pct:number;adverse_candle_failsafe:FailSafe|null};
type Contract={exit_minutes:number|null;contract_policy:string|null};
type Execution=Record<string,Record<string,Value>>;
type Configuration={execution:Execution;execution_overrides:Execution;policy_warning?:string|null;entry:Input[];revision:string;scope:string;mode:string;native_exit:string;exit_policy:(Profit&{rule:string;replace_native_exit:boolean})|null;selected_contract_timer:Contract|null;entry_editable:boolean;risk:Record<string,number|null>;account_risk:Record<string,number|null>;risk_overrides:Record<string,number|null>;profit_overrides:Profit|null;contract_timer_overrides:Contract|null;contract_editable:boolean};
const executionLabels:Record<string,string>={missing_structure_hold_minutes:'Missing chart data fallback (minutes)',minimum_open_interest:'Minimum outstanding contracts',maximum_spread_dollars:'Maximum bid/ask gap ($, 0 means no dollar cap)',minimum_dte:'Earliest expiration (days)',maximum_dte:'Latest expiration (days)',minimum_premium:'Minimum option price ($)',maximum_premium:'Maximum option price ($)',maximum_spread_pct:'Maximum bid/ask spread (fraction)',primary_policy:'How to rank eligible contracts',hold_minutes:'Exit after this many minutes',max_hold_bars:'Maximum completed bars held',legacy_arm_dollars:'Start profit protection at ($ per contract)',legacy_giveback_pct:'Peak profit giveback (%)',partial_gain_pct:'First sale at option gain (%)',final_gain_pct:'Final sale at option gain (%)'};
const contracts=[['closest_otm_150_1000','Closest out-of-the-money'],['nearest_weekly_150_1000','Nearest weekly expiration'],['tightest_spread_150_1000','Smallest bid/ask gap'],['lowest_ask_150_1000','Lowest asking price'],['highest_open_interest_150_1000','Most outstanding contracts'],['highest_volume_150_1000','Most contracts traded'],['target_150_250','Cost $150 to $250, closest to $200']];
export function StrategyConfiguration({strategy,ticker,version}:{strategy:string;ticker:string;version:string}){
 const [data,setData]=useState<Configuration|null>(null);const [values,setValues]=useState<Record<string,Value>>({});const [risk,setRisk]=useState<Record<string,number|null>>({});const [profit,setProfit]=useState<Profit|null>(null);const [contract,setContract]=useState<Contract|null>(null);const [execution,setExecution]=useState<Execution>({});const [error,setError]=useState('');const [busy,setBusy]=useState(false);const [saved,setSaved]=useState(false);const [confirmSave,setConfirmSave]=useState(false);
 const url=`/api/settings/strategies/${encodeURIComponent(strategy)}/${encodeURIComponent(ticker)}/configuration`;
 function accept(d:Configuration){setData(d);setValues(Object.fromEntries(d.entry.map(f=>[f.key,f.value])));setRisk(d.risk_overrides);setProfit(d.profit_overrides);setContract(d.contract_timer_overrides);setExecution(d.execution_overrides);}
 async function load(){setBusy(true);setError('');try{const r=await fetch(`${url}?version=${encodeURIComponent(version)}`,{credentials:'include'});const d=await r.json();if(!r.ok)throw new Error(d.detail||'Could not load configuration');accept(d);}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
 async function save(){if(!data)return;setConfirmSave(false);setBusy(true);setError('');setSaved(false);try{const r=await fetch(url,{method:'PUT',credentials:'include',headers:{'Content-Type':'application/json'},body:JSON.stringify({version,scope:data.scope,revision:data.revision,entry:values,risk,profit,contract_timer:contract,execution})});const d=await r.json();if(!r.ok)throw new Error(typeof d.detail==='string'?d.detail:'Check the settings and try again.');accept(d);setSaved(true);}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
 const activeProfit=profit??data?.exit_policy;

 function changeProfit(key:'gain_pct'|'giveback_pct'|'partial_sell_pct',value:number){if(activeProfit)setProfit({partial_sell_pct:activeProfit.partial_sell_pct??50,gain_pct:activeProfit.gain_pct,giveback_pct:activeProfit.giveback_pct,adverse_candle_failsafe:activeProfit.adverse_candle_failsafe??null,[key]:value});setSaved(false);}
 function changeFailSafe(value:FailSafe|null){if(activeProfit)setProfit({partial_sell_pct:activeProfit.partial_sell_pct??50,gain_pct:activeProfit.gain_pct,giveback_pct:activeProfit.giveback_pct,adverse_candle_failsafe:value});setSaved(false);}
 return <details className="mt-3" onToggle={e=>{if(e.currentTarget.open&&!data&&!busy)void load();}}><summary className="cursor-pointer font-semibold">Configure {ticker}</summary>
 {busy&&<p role="status">Loading or saving...</p>}{error&&<p role="alert" className="text-red-600">{error} <button className="btn btn-ghost" onClick={load}>Reload saved settings</button></p>}
 {data&&<div className="space-y-4 pt-3"><p className="text-xs text-ink-muted">{ticker} · {data.mode} · Version {version}. Changes apply to future setups. Opening this panel changes nothing.</p>
 {data.policy_warning&&<p role="alert" className="text-amber-700">{data.policy_warning} Showing the newly assigned exit. New entries remain stopped for this configuration until you save.</p>}<section><h5 className="font-semibold">Entry checks</h5>{!data.entry_editable&&<p>These entry inputs are still fixed in the strategy code. Editing is not connected yet.</p>}<div className="grid grid-cols-1 sm:grid-cols-2 gap-3 mt-2">{data.entry.map(f=><label className="text-sm" key={f.key}>{f.label}{f.type==='boolean'?<input className="ml-2" type="checkbox" checked={Boolean(values[f.key])} onChange={e=>{setValues({...values,[f.key]:e.target.checked});setSaved(false);}}/>:<input className="input w-full mt-1" type={f.type} step={f.type==='number'?'any':undefined} value={String(values[f.key]??'')} onChange={e=>{setValues({...values,[f.key]:f.type==='number'?Number(e.target.value):e.target.value});setSaved(false);}}/>}<span className="block text-xs text-ink-muted">Engine default: {String(f.default)}{f.type==='time'?' Eastern':''}</span></label>)}</div></section>
 <section><h5 className="font-semibold">Position size</h5><p className="text-xs text-ink-muted">Account loss limits and buying-power checks still apply. Sizing uses the engine’s enforceable risk estimate.</p><div className="grid sm:grid-cols-2 gap-3 mt-2">{[['risk_per_trade','Risk per trade (%)',100],['max_position_dollars_pct','Maximum position cost (% of account)',1]].map(([key,label,multiplier])=>{const k=String(key),scale=Number(multiplier),v=k in risk?risk[k]:data.account_risk[k];return <label key={k} className="text-sm">{label}<input type="number" step="any" className="input w-full" value={v==null?'':v*scale} placeholder="Account default" onChange={e=>{setRisk({...risk,[k]:e.target.value===''?null:Number(e.target.value)/scale});setSaved(false);}}/><button className="text-xs" onClick={()=>{const next={...risk};delete next[k];setRisk(next);setSaved(false);}}>Use account default</button></label>;})}</div></section>
 <section><h5 className="font-semibold">Exit rules</h5>{activeProfit&&data.exit_policy?.rule==='trend_partial_profit'?<><p>Sell the configured share at the gain below, then trail the remaining contracts. The first sale rounds down to whole contracts. If it rounds to zero, all contracts trail after activation. Giveback is a percentage of profit, not the full option price.</p><div className="grid sm:grid-cols-2 gap-3 mt-2"><label>Contracts to sell at first target (%)<input className="input w-full" type="number" min="0.01" max="99.99" step="any" value={activeProfit.partial_sell_pct??50} onChange={e=>changeProfit('partial_sell_pct',Number(e.target.value))}/></label><label>First sale at gain (%)<input className="input w-full" type="number" step="any" value={activeProfit.gain_pct} onChange={e=>changeProfit('gain_pct',Number(e.target.value))}/></label><label>Peak profit giveback (%)<input className="input w-full" type="number" step="any" value={activeProfit.giveback_pct} onChange={e=>changeProfit('giveback_pct',Number(e.target.value))}/></label></div><label className="block mt-3"><input type="checkbox" checked={!!activeProfit.adverse_candle_failsafe} onChange={e=>changeFailSafe(e.target.checked?{timeframe_minutes:5,consecutive_candles:3,loss_pct:10}:null)}/> Candle and option-loss fail-safe before profit activation</label>{activeProfit.adverse_candle_failsafe&&<div className="grid sm:grid-cols-2 gap-3 mt-2"><label>Fail-safe candle timeframe<select className="input w-full" value={activeProfit.adverse_candle_failsafe.timeframe_minutes} onChange={e=>changeFailSafe({...activeProfit.adverse_candle_failsafe!,timeframe_minutes:Number(e.target.value)})}>{[1,2,3,4,5,10,15,20,30,60].map(n=><option key={n} value={n}>{n} minute{n===1?'':'s'}</option>)}</select></label><label>Consecutive adverse completed candles<input className="input w-full" type="number" value={activeProfit.adverse_candle_failsafe.consecutive_candles} onChange={e=>changeFailSafe({...activeProfit.adverse_candle_failsafe!,consecutive_candles:Number(e.target.value)})}/></label><label>Option loss (%)<input className="input w-full" type="number" step="any" value={activeProfit.adverse_candle_failsafe.loss_pct} onChange={e=>changeFailSafe({...activeProfit.adverse_candle_failsafe!,loss_pct:Number(e.target.value)})}/></label><p className="text-xs col-span-full">Both conditions must be met. This protection turns off at +{activeProfit.gain_pct}% profit.</p></div>}</>:<p>{data.native_exit}</p>}{data.exit_policy?.replace_native_exit===true&&<p className="text-xs mt-2">Native timer replaced. Safety exits and session close remain active.</p>}</section>
 {Object.entries(data.execution??{}).map(([section,fields])=>Object.keys(fields).length>0&&<section key={section}><h5 className="font-semibold">{section==='contract'?'Option contract filters':'Native exit parameters'}</h5><p className="text-xs text-ink-muted">{section==='contract'?'Premium is the option price per share. One contract costs 100 times that price. Spread is a fraction: 0.08 means 8%. Account capacity and quote-validity checks still apply.':'These values control the native exit. Mandatory account safety and session close remain active.'}</p><div className="grid sm:grid-cols-2 gap-3 mt-2">{Object.entries(fields).map(([key,value])=>{const actual=execution[section]?.[key]??value;function change(v:Value){setExecution({...execution,[section]:{...fields,...execution[section],[key]:v}});setSaved(false);}return <label key={key} className="text-sm">{executionLabels[key]??key.replaceAll('_',' ')}{typeof value==='string'?<select className="input w-full" value={String(actual)} onChange={e=>change(e.target.value)}>{!contracts.some(([v])=>v===actual)&&<option value={String(actual)}>Current strategy ranking</option>}{contracts.map(([v,label])=><option key={v} value={v}>{label}</option>)}</select>:<input className="input w-full" type="number" step="any" value={Number(actual)} onChange={e=>change(Number(e.target.value))}/>}</label>;})}</div></section>)}

 {data.contract_editable&&!data.exit_policy?.replace_native_exit&&<label className="block text-sm">Optional time-limit override<select className="input w-full" value={(contract?contract.exit_minutes:data.selected_contract_timer?.exit_minutes)??''} onChange={e=>{setContract({...contract,contract_policy:contract?.contract_policy??data.selected_contract_timer?.contract_policy??null,exit_minutes:e.target.value===''?null:Number(e.target.value)});const next={...execution};if(next.native_exit){next.native_exit={...next.native_exit};delete next.native_exit.hold_minutes;}setExecution(next);setSaved(false);}}><option value="">Use native exit parameters above</option>{[30,60,90,120].map(n=><option key={n} value={n}>{n} minutes</option>)}</select><span className="text-xs text-ink-muted">Choosing a time limit replaces the native strategy exit. Safety exits and session close still apply.</span></label>}

 <button className="btn btn-primary" disabled={busy} onClick={()=>setConfirmSave(true)}>Save {ticker} configuration</button>{confirmSave&&<div className="rounded border p-3" role="group" aria-label="Confirm configuration"><p>Save these settings for new {ticker} setups in this {data.mode} account? Existing positions keep their entry-time exit.</p><button className="btn btn-primary" disabled={busy} onClick={save}>Confirm save</button><button className="btn btn-ghost" onClick={()=>setConfirmSave(false)}>Cancel</button></div>}{saved&&<p role="status">Saved for future setups. Strategy switches and existing positions were not changed.</p>}</div>}</details>;
}
